        i++;
      }
    }
    out.push(line);
  }
  if (i < words.length) truncated = true;
  if (truncated && out.length > 0) {
    const last = out[out.length - 1]!;
    out[out.length - 1] = last.length >= width ? last.slice(0, Math.max(0, width - 1)) + "…" : last + "…";
