import { Resvg } from "@resvg/resvg-js";
import { faceImage, measure } from "C:/Users/xbox/ScrtGit/sbm-ui/streamdeck/src/face.ts";

const render = (title: string) => {
  const svg = Buffer.from(faceImage({ title, tone: "live" }).split(",")[1]!, "base64").toString("utf8");
  const png = new Resvg(svg, { fitTo: { mode: "width", value: 144 }, font: { loadSystemFonts: true } }).render();
  return { pixels: png.pixels, w: png.width, h: png.height, svg };
};

// The same face with no title draws the same ground and the same frame, so
// the pixels that differ are the title's ink and nothing else.
const blank = render("");

const phrases = [
  "Not connected",
  "Nothing to undo",
  "Nothing to press",
  "That run has ended",
  "Idle · press to connect",
  "Tick everything and Next",
  "Draw what is wrong with the world",
  "WWWWW",
  "4/10",
  "Connecting",
  "Undo",
];

console.log("phrase | size | lines | min x | max x | widest measured");
for (const p of phrases) {
  const { pixels, w, h, svg } = render(p);
  let min = Infinity;
  let max = -Infinity;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = (y * w + x) * 4;
      const d =
        Math.abs(pixels[i]! - blank.pixels[i]!) + Math.abs(pixels[i + 1]! - blank.pixels[i + 1]!) + Math.abs(pixels[i + 2]! - blank.pixels[i + 2]!);
      if (d > 12) {
        if (x < min) min = x;
        if (x > max) max = x;
      }
    }
  }
  const size = Number(/font-size="(\d+)" font-weight/.exec(svg)![1]);
